import {createProcessorUncached} from '../../packages/docusaurus-mdx-loader/src/processor.ts';

const mdContent = `import Tabs from '@theme/Tabs';
import TabItem from '@theme/TabItem';

# Hello

<Tabs>
  <TabItem value="a" label="A">
    Content A
  </TabItem>
  <TabItem value="b" label="B">
    Content B
  </TabItem>
</Tabs>
`;

const options = {
  staticDirs: [],
  siteDir: '',
  admonitions: true,
  markdownConfig: {
    format: 'detect',
    mermaid: false,
    mdx1Compat: {comments: true, admonitions: true, headingIds: true},
    remarkRehypeOptions: undefined,
    preprocessor: undefined,
    parseFrontMatter: undefined,
  },
};

async function run(content, label) {
  const processor = await createProcessorUncached({
    options,
    format: 'mdx',
  });
  try {
    const result = await processor.process({
      content,
      filePath: '/tmp/test.mdx',
      frontMatter: {},
      compilerName: 'client',
    });
    console.log(`=== ${label} ===`);
    console.log(result.content.slice(0, 3000));
