const mdContent = `import Tabs from '@theme/Tabs';
import TabItem from '@theme/TabItem';

# Hello

<Tabs>
  <TabItem value="a" label="A">
    Content A
  </TabItem>
</Tabs>
`;

const options: any = {
  staticDirs: [],
  siteDir: '',
  admonitions: true,
  markdownConfig: {
    format: 'detect',
    mermaid: false,
    mdx1Compat: {comments: true, admonitions: true, headingIds: true},
  },
};

describe('repro CRLF', () => {
  it('LF works', async () => {
    const processor = await createProcessorUncached({options: options as any, format: 'mdx'});
    const result = await processor.process({
      content: mdContent,
      filePath: '/tmp/test.mdx',
      frontMatter: {},
      compilerName: 'client',
    });
    console.log(result.content.slice(0, 2000));
  });

  it('CRLF', async () => {
    const processor = await createProcessorUncached({options: options as any, format: 'mdx'});
    const result = await processor.process({
      content: mdContent.replace(/\n/g, '\r\n'),
      filePath: '/tmp/test.mdx',
      frontMatter: {},
      compilerName: 'client',
    });
    console.log(JSON.stringify(result.content.slice(0, 2500)));
  });
});

