const {createProcessorUncached} = require('/testbed/packages/docusaurus-mdx-loader/lib/processor.js');

const mdContent = `import Tabs from '@theme/Tabs';
import TabItem from '@theme/TabItem';

# Hello

<Tabs>
  <TabItem value="a" label="A">
    Content A
  </TabItem>
</Tabs>
`;

const options = {
  staticDirs: [],
  siteDir: '',
  admonitions: true,
  remarkPlugins: [],
  markdownConfig: {
    format: 'detect',
    mermaid: false,
    mdx1Compat: {comments: true, admonitions: true, headingIds: true},
  },
};

async function run(content, label) {
  const processor = await createProcessorUncached({options, format: 'mdx'});
  try {
    const result = await processor.process({
      content,
      filePath: '/tmp/test.mdx',
      frontMatter: {},
      compilerName: 'client',
    });
    console.log(`=== ${label} OK ===`);
    console.log(result.content);
  } catch (e) {
    console.log(`=== ${label} FAILED === ${e.message}`);
  }
}

(async () => {
  await run(mdContent, 'LF');
  await run(mdContent.replace(/\n/g, '\r\n'), 'CRLF');
})();

