import logger from '@docusaurus/logger';
import matter from 'gray-matter';
import {
  createSlugger,
  MdxCodeFence,
  type Slugger,
  type SluggerOptions,
} from './slugger';
import type {
  ParseFrontMatter,
  DefaultParseFrontMatter,
